"""Report templates: the block trees are generated by the TypeScript package; this fills in the prefix and subject."""

from __future__ import annotations

import re
from typing import Any

from ..inline import JS_SPACE, js_trim
from ..validation import js_length
from .spec import spec

PREFIX_SENTINEL = "ZZPFXZZ"
SUBJECT_SENTINEL = "ZZSUBJZZ"
SUBJECT_MAX = 200

_TEMPLATE_PREFIX = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,59}\Z", re.ASCII)
_SENTINELS = re.compile(PREFIX_SENTINEL + "|" + SUBJECT_SENTINEL)


def collapse_space(text: str) -> str:
    """Replace every run of JavaScript whitespace with one space."""
    out: list[str] = []
    in_run = False
    for ch in text:
        if ch in JS_SPACE:
            if not in_run:
                out.append(" ")
            in_run = True
            continue
        in_run = False
        out.append(ch)
    return "".join(out)


def clean_subject(value: str) -> str:
    """Collapse whitespace and drop control characters so a subject cannot break the one-line titles."""
    out: list[str] = []
    in_run = False
    for ch in value:
        if ord(ch) <= 0x1F or ord(ch) == 0x7F:
            if not in_run:
                out.append(" ")
            in_run = True
            continue
        in_run = False
        out.append(ch)
    cleaned = js_trim(collapse_space("".join(out)))
    if js_length(cleaned) > SUBJECT_MAX:
        raise ValueError(f"subject must be at most {SUBJECT_MAX} characters.")
    return cleaned


def is_template_kind(kind: str) -> bool:
    return kind in spec().template_kinds


def _substitute(value: Any, prefix: str, subject: str) -> Any:
    if isinstance(value, str):
        # One pass, so a subject that happens to contain the other sentinel is not substituted twice.
        return _SENTINELS.sub(lambda m: prefix if m.group(0) == PREFIX_SENTINEL else subject, value)
    if isinstance(value, list):
        return [_substitute(e, prefix, subject) for e in value]
    if isinstance(value, dict):
        return {k: _substitute(e, prefix, subject) for k, e in value.items()}
    return value


def create_template(kind: str, prefix: str, subject: str, parent_id: str | None) -> list[dict[str, Any]]:
    """The ordered blocks of a report template. Raises ValueError for an unknown kind or a bad prefix."""
    if not is_template_kind(kind):
        raise ValueError(f'Unknown template "{kind}". Use one of: {", ".join(spec().template_kinds)}.')
    if not _TEMPLATE_PREFIX.match(prefix):
        raise ValueError(
            "idPrefix must start with a letter or digit and use only letters, digits, dot, underscore, colon and "
            "hyphen (at most 60 characters)."
        )
    entry = spec().templates[kind]
    blocks: list[dict[str, Any]] = _substitute(entry["withSubject" if subject else "withoutSubject"], prefix, subject)
    for block in blocks:
        if block.get("parentId") is None:
            block["parentId"] = parent_id
    return blocks


def template_title(kind: str, subject: str) -> str:
    cleaned = clean_subject(subject) if subject else ""
    base = spec().template_titles[kind]
    if not cleaned or kind == "blank":
        return base
    return cleaned + ": " + base[:1].lower() + base[1:]
